html, body, #root { height: 100%; margin: 0; }
body { background: var(--paper); color: var(--ink); font-family: var(--font); font-size: 13px; }
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; padding: 0; }

/* ---------- layout ---------- */
.app { position: relative; min-width: 1280px; min-height: 820px; height: 100%; overflow: hidden; }
.app__glow { position: absolute; inset: 15% 18% 20%; background: #fff; opacity: 0.55; filter: blur(70px); border-radius: 50%; pointer-events: none; }
.app__brand { position: absolute; left: 24px; top: 24px; }
.app__top { position: absolute; left: 50%; top: 20px; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 10px; }
.app__left { position: absolute; left: 24px; top: 92px; width: 256px; display: flex; flex-direction: column; gap: 12px; }
.app__right { position: absolute; right: 24px; top: 20px; width: 256px; display: flex; flex-direction: column; gap: 12px; }
.app__world { position: absolute; left: 296px; right: 296px; top: 150px; bottom: 100px; }
.app__dock { position: absolute; left: 50%; bottom: 24px; transform: translateX(-50%); }

/* ---------- primitives ---------- */
.card { background: var(--card); border: 1px solid var(--line); border-radius: var(--r-card); box-shadow: var(--shadow-card); padding: 16px; display: flex; flex-direction: column; gap: 12px; }
.title { font-family: var(--display); font-weight: 700; font-size: 15px; }
.caps { font-size: 10px; font-weight: 700; color: var(--muted); letter-spacing: 0.02em; text-transform: uppercase; }
.muted { color: var(--muted); font-size: 11px; }
.row { display: flex; align-items: center; gap: 8px; }
.between { display: flex; align-items: center; justify-content: space-between; gap: 8px; }

.chip { display: inline-flex; align-items: center; gap: 4px; padding: 3px 8px; border-radius: 8px; font-size: 10px; font-weight: 700; white-space: nowrap; }
.tone-ink { background: var(--ink); color: #fff; }
.tone-coral { background: #ffe8e2; color: var(--coral); }
.tone-mint { background: #ddf5ea; color: var(--mint); }
.tone-amber { background: #fff3d6; color: #8a5a00; }
.tone-violet { background: #eeeaff; color: var(--violet); }
.tone-muted { background: var(--track); color: var(--muted); }

.bar { position: relative; height: 6px; border-radius: 99px; background: var(--track); overflow: hidden; }
.bar__fill { position: absolute; inset: 0 auto 0 0; border-radius: 99px; }
.bar__tick { position: absolute; top: 0; bottom: 0; width: 2px; background: var(--ink); }

.hud { position: absolute; transform: translateX(-50%); display: flex; align-items: center; gap: 6px; padding: 4px 8px 4px 5px; border-radius: 11px; background: #fff; box-shadow: var(--shadow-pop); font-size: 11px; font-weight: 600; white-space: nowrap; cursor: pointer; }
.hud--selected { outline: 1.5px solid var(--ink); }
.hud--alert { background: var(--coral); color: #fff; }
.hud__lv { width: 18px; height: 18px; border-radius: 8px; background: var(--ink); color: #fff; display: grid; place-items: center; font-size: 10px; font-weight: 700; }
.hud--alert .hud__lv { background: #fff; color: var(--coral); }
.hud .bar { width: 34px; height: 5px; }

/* ---------- controls ---------- */
.brand { display: flex; align-items: center; gap: 10px; }
